// CC0: Duo-level truchet
//  Experimenting with duo level truchet with multiple tiles

#define TIME        iTime
#define RESOLUTION  iResolution
#define PI          3.141592654
#define TAU         (2.0*PI)

#define ROT(a)      mat2(cos(a), sin(a), -sin(a), cos(a))

const float w_0 = 0.11;
const float w_1 = 0.195;

// License: Unknown, author: Unknown, found: don't remember
float hash(vec2 co) {
  return fract(sin(dot(co.xy ,vec2(12.9898,58.233))) * 13758.5453);
}

float circle(vec2 p, float r) {
  return length(p) - r;
}

vec2 mod2_1(inout vec2 p) {
  p += 0.5;
  vec2 c = floor(p);
  p = fract(p) - 0.5;
  return c;
}

float df_0_0(vec2 p) {
  float d0 = circle(p-0.5, 0.5);
  float d1 = circle(p+0.5, 0.5);
  float d = d0;
  d = min(d, d1);
  d = abs(d) - w_0;
  d = -d;
  return d;
}

float df_0_1(vec2 p) {
  vec2 ap = abs(p);
  float d0 = ap.x;
  float d1 = ap.y;
  float d2 = circle(p, 2.0*w_0);
  float d = d0;
  d = min(d, d1);
  d = min(d, d2);
  d = abs(d) - w_0;
  d = -d;
  return d;
}

float df_0_2(vec2 p) {
  vec2 ap = abs(p);
  float d0 = length(ap-vec2(0.5, 0.0));
  float d1 = length(ap-vec2(0.0, 0.5));
  float d = d0;
  d = min(d, d1);
  d = abs(d) - w_0;
  d = -d;
  return d;
}

float df_0_3(vec2 p) {
  float d0 = length((p)-vec2(0.5, 0.0));
  float d1 = length((p)-vec2(0.0, 0.5));
  float d2 = circle(p+0.5, 0.5);
  float d = d0;
  d = min(d, d1);
  d = min(d, d2);
  d = abs(d) - w_0;
  d = -d;
  return d;
}

float df_0_4(vec2 p) {
  vec2 ap = p;
  ap.x = abs(ap.x);
  float d0 = length(ap-vec2(0.5, 0.0));
  float d1 = ap.x;
  float d = d0;
  d = min(d, d1);
  d = abs(d) - w_0;
  d = -d;
  return d;
}

float df_1_0(vec2 p) {
  vec2 ap = abs(p);
  float d0 = circle(p-0.5, 0.5);
  float d1 = circle(p+0.5, 0.5);
  float d2 = circle(ap-0.5, w_1);
  float d = d0;
  d = min(d, d1);
  d = abs(d) - w_1;
  d = min(d, d2);
  return d;
}

float df_1_1(vec2 p) {
  vec2 ap = abs(p);
  float d0 = circle(ap-vec2(0.5, 0.0), (0.25));
  float d1 = circle(ap-vec2(0.0, 0.5), (0.25));
  float d = d0;
  d = min(d, d1);
  d = abs(d) - 0.5*w_0;
  d = -d;
  return d;
}

float df_1_2(vec2 p) {
  vec2 ap = (p);
  ap.x = abs(p.x);
  float d0 = circle(ap-vec2(0.5, 0.0), (0.25));
  float d1 = abs(ap.x-0.25);
  float d = d0;
  d = min(d, d1);
  d = abs(d) - 0.5*w_0;
  d = -d;
  return d;
}


float df_1_3(vec2 p) {
  float d0 = (circle(p-0.5, 0.75));
  float d1 = (circle(p-vec2(-0.5, 0.0), (0.25)));
  float d2 = (circle(p-vec2(0.0, -0.5), (0.25)));
  float d3 = abs(circle(p-0.5, 0.25))-0.5*w_0;

  float d = d0;
  d = min(d, d1);
  d = min(d, d2);
  d = abs(d) - 0.5*w_0;
  d = min(d, d3);
  d = -d;
  return d;
}

const mat2 rots[4] = mat2[4](
    ROT(0.0*TAU/4.0)
  , ROT(1.0*TAU/4.0)
  , ROT(2.0*TAU/4.0)
  , ROT(3.0*TAU/4.0))
  ;

float df(vec2 p) {
  vec2 pp0 = p;
  vec2 np0 = mod2_1(pp0);
  float h0_0 = hash(np0);
  float h1_0 = fract(8677.0*h0_0);
  float h2_0 = fract(3677.0*h0_0);

  if (h2_0 > 0.5) {
    vec2 pp1 = p*2.0;
    pp1 += 0.5;
    vec2 np1 = mod2_1(pp1);
    float h1_0 = hash(np1);
    float h1_1 = fract(8677.0*h1_0);
    pp1 *= rots[int(h1_0*4.0)];
    float d1 = 0.0;
    if (h1_1 > 0.85) {
      d1 = df_0_4(pp1);
    } else if (h1_1 > 0.75) {
      d1 = df_0_3(pp1);
    } else if (h1_1 > 0.55) {
      d1 = df_0_2(pp1);
    } else if (h1_1 > 0.4) {
      d1 = df_0_1(pp1);
    } else {
      d1 = df_0_0(pp1);
    }
    d1 *= 0.5;
    return d1;
  }

  pp0 *= rots[int(h0_0*4.0)];
  float d0 = 0.0;
  if (h1_0 > 0.9) {
    d0 = df_1_3(pp0);
  } else if (h1_0 > 0.7){
    d0 = df_1_2(pp0);  
  } else if (h1_0 > 0.5){
    d0 = df_1_1(pp0);  
  } else {
    d0 = df_1_0(pp0);
  }
  return d0;
}

vec3 effect(vec2 p, vec2 pp) {
  float ll = length(pp);

  float aa = 2.0/RESOLUTION.y;

  const float sz = 0.333;

  const float a = 10.0;
  p += sin(0.25*vec2(1.0, sqrt(0.5))*TIME/a)*a;
  float d = df(p/sz)*sz;
  vec3 col = vec3(0.0);
  col = mix(col, vec3(0.5), smoothstep(aa, -aa, d));
  col *= smoothstep(1.5, 0.5, ll);
  return col;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
  vec2 q = fragCoord/RESOLUTION.xy;
  vec2 p = -1. + 2. * q;
  vec2 pp = p;
  p.x *= RESOLUTION.x/RESOLUTION.y;
  vec3 col = effect(p, pp);  
  col = sqrt(col);
  fragColor = vec4(col, 1.0);
}
